--- a/static/game_snake.html
+++ b/static/game_snake.html
@@ -0,0 +1,191 @@
+<!DOCTYPE html>
+<html>
+<head>
+    <title>Cyber-Grid Snake Game</title>
+    <style>
+        body {
+            background-color: #2f2f2f;
+            font-family: Arial, sans-serif;
+        }
+        #game-container {
+            width: 400px;
+            height: 400px;
+            border: 1px solid #ccc;
+            margin: 20px auto;
+        }
+        #score {
+            font-size: 24px;
+            font-weight: bold;
+            color: #fff;
+        }
+    </style>
+</head>
+<body>
+    <div id="game-container"></div>
+    <div id="score">Score: 0</div>
+    <button id="start-button">Start Game</button>
+    <button id="sound-toggle">Toggle Sound</button>
+    <script>
+        // Game logic and rendering
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let score = 0;
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let speedBoost = false;
+        let doublePoints = false;
+        let shield = false;
+        let soundOn = true;
+        let gameInterval;
+        
+        // Draw the game board
+        function drawBoard() {
+            const gameContainer = document.getElementById('game-container');
+            gameContainer.innerHTML = '';
+            for (let i = 0; i < 40; i++) {
+                for (let j = 0; j < 40; j++) {
+                    const cell = document.createElement('div');
+                    cell.style.position = 'absolute';
+                    cell.style.left = i * 10 + 'px';
+                    cell.style.top = j * 10 + 'px';
+                    cell.style.width = '10px';
+                    cell.style.height = '10px';
+                    cell.style.border = '1px solid #ccc';
+                    gameContainer.appendChild(cell);
+                }
+            }
+        }
+        
+        // Draw the snake
+        function drawSnake() {
+            const gameContainer = document.getElementById('game-container');
+            gameContainer.innerHTML = '';
+            for (let i = 0; i < snake.length; i++) {
+                const cell = document.createElement('div');
+                cell.style.position = 'absolute';
+                cell.style.left = snake[i].x + 'px';
+                cell.style.top = snake[i].y + 'px';
+                cell.style.width = '10px';
+                cell.style.height = '10px';
+                cell.style.background = 'green';
+                gameContainer.appendChild(cell);
+            }
+        }
+        
+        // Draw the food
+        function drawFood() {
+            const gameContainer = document.getElementById('game-container');
+            const foodCell = document.createElement('div');
+            foodCell.style.position = 'absolute';
+            foodCell.style.left = food.x + 'px';
+            foodCell.style.top = food.y + 'px';
+            foodCell.style.width = '10px';
+            foodCell.style.height = '10px';
+            foodCell.style.background = 'red';
+            gameContainer.appendChild(foodCell);
+        }
+        
+        // Handle keyboard input
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (e.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (e.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (e.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        });
+        
+        // Handle touch input
+        document.addEventListener('touchstart', (e) => {
+            if (e.touches[0].clientX < window.innerWidth / 2 && direction !== 'right') {
+                direction = 'left';
+            } else if (e.touches[0].clientX > window.innerWidth / 2 && direction !== 'left') {
+                direction = 'right';
+            }
+        });
+        
+        // Update the game state
+        function updateGameState() {
+            // Move the snake
+            for (let i = snake.length - 1; i > 0; i--) {
+                snake[i].x = snake[i - 1].x;
+                snake[i].y = snake[i - 1].y;
+            }
+            if (direction === 'up') {
+                snake[0].y -= 10;
+            } else if (direction === 'down') {
+                snake[0].y += 10;
+            } else if (direction === 'left') {
+                snake[0].x -= 10;
+            } else if (direction === 'right') {
+                snake[0].x += 10;
+            }
+            
+            // Check for collisions with the wall or itself
+            if (snake[0].x < 0 || snake[0].x >= 400 || snake[0].y < 0 || snake[0].y >= 400 || checkCollision()) {
+                // Game over
+                clearInterval(gameInterval);
+                alert('Game Over!');
+            }
+            
+            // Check for food collision
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                // Increase score and spawn new food
+                score++;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+                // Add speed boost, double points, or shield
+                if (Math.random() < 0.2) {
+                    speedBoost = true;
+                    setTimeout(() => {
+                        speedBoost = false;
+                    }, 5000);
+                } else if (Math.random() < 0.3) {
+                    doublePoints = true;
+                    setTimeout(() => {
+                        doublePoints = false;
+                    }, 5000);
+                } else if (Math.random() < 0.1) {
+                    shield = true;
+                    setTimeout(() => {
+                        shield = false;
+                    }, 5000);
+                }
+            }
+            
+            // Update the score
+            document.getElementById('score').innerText = 'Score: ' + score;
+            
+            // Draw the game board, snake, and food
+            drawBoard();
+            drawSnake();
+            drawFood();
+        }
+        
+        // Check for collision with itself
+        function checkCollision() {
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    return true;
+                }
+            }
+            return false;
+        }
+        
+        // Start the game
+        document.getElementById('start-button').addEventListener('click', () => {
+            gameInterval = setInterval(updateGameState, 100);
+        });
+        
+        // Toggle sound
+        document.getElementById('sound-toggle').addEventListener('click', () => {
+            soundOn = !soundOn;
+        });
+    </script>
+</body>
+</html>
